/* NOCTURNE — local-first personal dashboard */
(() => {
  "use strict";
  const KEY = "nocturne.data.v1";
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const uid = () => (crypto.randomUUID ? crypto.randomUUID() : Date.now().toString(36)+Math.random().toString(36).slice(2));
  const todayKey = (date=new Date()) => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;
  const dayLabel = (iso) => { if(!iso) return "No date"; const d=new Date(iso+"T12:00:00"); return d.toLocaleDateString(undefined,{month:"short",day:"numeric"}); };
  const niceDate = (d=new Date(), opts={weekday:"long",month:"long",day:"numeric"}) => d.toLocaleDateString(undefined,opts);
  const escapeHTML = s => String(s ?? "").replace(/[&<>"']/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
  const defaultData = () => ({
    version:1, profile:{name:"Lour",workspace:"Personal workspace",quote:"Small steps still move you forward.",accent:"violet"},
    settings:{focus:25,shortBreak:5,longBreak:15,longEvery:4,weekStartsMonday:true,showCompleted:false,confirmDelete:true},
    tasks:[],goals:[],habits:[],habitLogs:{},notes:[],journal:[],sessions:[],activity:[],archived:[],widgets:["tasks","habits","activity"],createdAt:new Date().toISOString()
  });
  let data = loadData(), currentView="overview", taskFilter="all", taskQuery="", calendarDate=new Date(), selectedDate=todayKey(), timerMode="focus", timerRemaining=data.settings.focus*60, timerInterval=null, timerRunning=false, sessionStartedAt=null, currentModal=null, searchIndex=0;
  function loadData(){try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);return {...defaultData(),...parsed,settings:{...defaultData().settings,...parsed.settings},profile:{...defaultData().profile,...parsed.profile}}}}catch(e){console.warn("Could not read saved data",e)}return defaultData()}
  function save(){try{localStorage.setItem(KEY,JSON.stringify(data));$("#saveStatus").textContent="Saved locally · "+new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"});}catch(e){toast("Storage is full. Export a backup and remove some data.","error")}}
  function logActivity(type,text){data.activity.unshift({id:uid(),type,text,at:new Date().toISOString()});data.activity=data.activity.slice(0,40);save()}
  function toast(message,type="success"){const el=document.createElement("div");el.className="toast "+type;el.textContent=message;$("#toastRegion").append(el);setTimeout(()=>el.remove(),3200)}
  function setView(view){currentView=view;$$(".nav-item[data-view]").forEach(b=>b.classList.toggle("active",b.dataset.view===view));$("#crumb").textContent=({"overview":"Analytics","tasks":"Tasks","calendar":"Calendar","focus":"Focus","goals":"Goals","habits":"Habits","journal":"Journal & Notes","insights":"Insights","settings":"Settings & backups"}[view]||"Overview");$("#sidebar").classList.remove("open");render();window.scrollTo({top:0,behavior:"smooth"})}
  function heading(kicker,title,desc,action=""){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${action}</div></div>`}
  function button(label,action,cls="primary-button"){return `<button class="${cls}" data-action="${action}">${label}</button>`}
  function empty(icon,title,desc,action,label){return `<div class="empty-state"><div class="empty-icon">${icon}</div><b>${title}</b><p>${desc}</p>${action?button(label||"Create new",action):""}</div>`}
  function priorityClass(p){return p==="High"?"priority-high":p==="Low"?"priority-low":"priority-medium"}
  function taskMeta(t){return `<span><i class="priority-dot ${priorityClass(t.priority)}"></i>${escapeHTML(t.priority||"Medium")}</span>${t.due?`<span>◷ ${dayLabel(t.due)}</span>`:""}${t.category?`<span class="tag">${escapeHTML(t.category)}</span>`:""}`}
  function taskRow(t){return `<div class="task-row"><input type="checkbox" class="check-circle" data-toggle-task="${t.id}" ${t.done?"checked":""} aria-label="Complete task"><div class="task-main"><div class="task-title ${t.done?"done":""}">${escapeHTML(t.title)}</div><div class="task-meta">${taskMeta(t)}</div></div><button class="small-icon" data-edit="task:${t.id}" title="Edit task">✎</button></div>`}
  function getTodayTasks(){const k=todayKey();return data.tasks.filter(t=>!t.done&&(t.due===k||!t.due)).sort((a,b)=>({High:0,Medium:1,Low:2}[a.priority]??1)-({High:0,Medium:1,Low:2}[b.priority]??1)).slice(0,5)}
  function isHabitDone(id,date=todayKey()){return !!(data.habitLogs[date]||[]).includes(id)}
  function completedToday(){return data.tasks.filter(t=>t.done&&t.completedAt?.slice(0,10)===todayKey()).length}
  let analyticsRange = "7";
  function renderOverview(){
    const now=new Date(), today=todayKey(now);
    const rangeDays=analyticsRange==="all"?null:Number(analyticsRange);
    const allDates=[data.createdAt,...data.tasks.map(t=>t.createdAt),...data.habits.map(h=>h.createdAt),...data.goals.map(g=>g.createdAt),...data.sessions.map(s=>s.at),...Object.keys(data.habitLogs).map(d=>d+"T12:00:00")].filter(Boolean).map(v=>new Date(v)).filter(d=>!Number.isNaN(d.getTime()));
    const earliest=allDates.length?new Date(Math.min(...allDates.map(d=>d.getTime()))):new Date(now);
    const start=new Date(now); if(rangeDays)start.setDate(start.getDate()-(rangeDays-1)); else {start.setTime(earliest.getTime());start.setHours(0,0,0,0)}
    const periodStart=todayKey(start), priorStart=new Date(start); if(rangeDays)priorStart.setDate(priorStart.getDate()-rangeDays); else priorStart.setTime(NaN);
    const inRange=(iso)=>!!iso&&iso.slice(0,10)>=periodStart&&iso.slice(0,10)<=today;
    const inPrior=(iso)=>!!rangeDays&&!!iso&&iso.slice(0,10)>=todayKey(priorStart)&&iso.slice(0,10)<periodStart;
    const days=[]; for(let d=new Date(start);todayKey(d)<=today;d.setDate(d.getDate()+1))days.push(todayKey(d));
    const priorDays=rangeDays?Array.from({length:rangeDays},(_,i)=>{const d=new Date(priorStart);d.setDate(d.getDate()+i);return todayKey(d)}):[];
    const rangeTasks=data.tasks.filter(t=>inRange(t.createdAt||t.completedAt));
    const priorTasks=data.tasks.filter(t=>inPrior(t.createdAt||t.completedAt));
    const taskDone=rangeTasks.filter(t=>t.done).length, taskOpen=rangeTasks.length-taskDone;
    const taskPct=rangeTasks.length?Math.round(taskDone/rangeTasks.length*100):0;
    const completedInRange=data.tasks.filter(t=>inRange(t.completedAt)).length;
    const completedPrior=data.tasks.filter(t=>inPrior(t.completedAt)).length;
    const habitCreatedOn=(h,iso)=>!h.createdAt||h.createdAt.slice(0,10)<=iso;
    let habitPossible=0,habitChecked=0,priorHabitPossible=0,priorHabitChecked=0;
    for(const iso of days){const active=data.habits.filter(h=>habitCreatedOn(h,iso));habitPossible+=active.length;habitChecked+=active.filter(h=>(data.habitLogs[iso]||[]).includes(h.id)).length}
    for(const iso of priorDays){const active=data.habits.filter(h=>habitCreatedOn(h,iso));priorHabitPossible+=active.length;priorHabitChecked+=active.filter(h=>(data.habitLogs[iso]||[]).includes(h.id)).length}
    const habitPct=habitPossible?Math.round(habitChecked/habitPossible*100):0;
    const focusInRange=data.sessions.filter(s=>inRange(s.at||s.date)).reduce((n,s)=>n+(Number(s.minutes)||0),0);
    const focusPrior=data.sessions.filter(s=>inPrior(s.at||s.date)).reduce((n,s)=>n+(Number(s.minutes)||0),0);
    const sessionsInRange=data.sessions.filter(s=>inRange(s.at||s.date));
    const focusSessions=sessionsInRange.filter(s=>s.mode==="focus").length;
    const goalsCompleted=data.goals.filter(g=>g.status==="Completed").length;
    const goalPct=data.goals.length?Math.round(data.goals.reduce((n,g)=>n+Math.max(0,Math.min(100,Number(g.progress)||0)),0)/data.goals.length):0;
    const scoreParts=[]; if(rangeTasks.length)scoreParts.push(taskPct); if(habitPossible)scoreParts.push(habitPct); if(data.goals.length)scoreParts.push(goalPct);
    const lifeScore=scoreParts.length?Math.round(scoreParts.reduce((a,b)=>a+b,0)/scoreParts.length):0;
    const tasks=getTodayTasks();
    const donut=(pct,first='#a18aff',second='#252744')=>`background:conic-gradient(${first} ${pct}%,${second} ${pct}% 100%)`;
    const trend=(current,prior,suffix="",invert=false)=>{if(!rangeDays)return `<span class="trend-neutral">All-time view</span>`;if(!prior)return `<span class="trend-neutral">No previous-period data</span>`;const delta=current-prior,good=invert?delta<=0:delta>=0;return `<span class="trend ${good?"trend-up":"trend-down"}">${delta>0?"↑":delta<0?"↓":"→"} ${Math.abs(delta)}${suffix} vs previous ${rangeDays}d</span>`};
    const pctTrend=(current,prior)=>!rangeDays?`<span class="trend-neutral">All-time view</span>`:prior===0?`<span class="trend-neutral">No previous-period data</span>`:`<span class="trend ${current>=prior?"trend-up":"trend-down"}">${current-prior>0?"↑":current-prior<0?"↓":"→"} ${Math.abs(current-prior)} pp vs previous ${rangeDays}d</span>`;
    const rangeLabel=analyticsRange==="all"?"All time":`Last ${rangeDays} days`;
    const priorityCounts=["High","Medium","Low"].map((p)=>({name:p,count:rangeTasks.filter(t=>(t.priority||"Medium")===p).length,color:p==="High"?"#f38ba8":p==="Medium"?"#b4a0ff":"#75d9cb"}));
    const statusCounts=[{name:"Completed",count:taskDone,color:"#a18aff"},{name:"In progress",count:rangeTasks.filter(t=>!t.done&&t.status==="In progress").length,color:"#75d9cb"},{name:"To do",count:rangeTasks.filter(t=>!t.done&&t.status!=="In progress").length,color:"#454766"}];
    const pie=(parts)=>{const sum=parts.reduce((n,p)=>n+p.count,0);let cursor=0;const stops=parts.map(p=>{const from=cursor;cursor+=sum?p.count/sum*100:0;return `${p.color} ${from}% ${cursor}%`}).join(",");return `background:conic-gradient(${stops||"#252744 0% 100%"})`};
    const legend=(parts,total)=>parts.map(p=>`<div><i class="legend-dot" style="background:${p.color}"></i><span>${p.name}</span><b>${p.count}</b></div>`).join("")+`<small>${total} total in this view</small>`;
    const focusDays=days.slice(-7).map(iso=>({iso,label:new Date(iso+"T12:00:00").toLocaleDateString(undefined,{weekday:"short"}),focus:data.sessions.filter(s=>s.date===iso).reduce((n,s)=>n+(Number(s.minutes)||0),0)}));
    const maxFocus=Math.max(1,...focusDays.map(d=>d.focus));
    return `${heading('YOUR PERSONAL ANALYTICS',`Your universe, ${escapeHTML(data.profile.name||'friend')}.`,'Your tracked patterns, trends, and progress in one place.',button('＋ Add a task','new-task'))}
      <div class="range-toolbar panel"><div><p class="eyebrow">ANALYTICS WINDOW</p><b>${rangeLabel}</b><small>${periodStart===today?niceDate(now,{month:"short",day:"numeric",year:"numeric"}):`${dayLabel(periodStart)} – ${dayLabel(today)}`}</small></div><div class="range-buttons">${[["7","7 days"],["30","30 days"],["90","90 days"],["all","All time"]].map(([v,l])=>`<button class="pill ${analyticsRange===v?"active":""}" data-analytics-range="${v}" aria-pressed="${analyticsRange===v}">${l}</button>`).join("")}</div></div>
      <div class="analytics-hero panel"><div class="analytics-intro"><p class="eyebrow">YOUR CURRENT SNAPSHOT</p><h2>Progress, in perspective.</h2><p>Period-based metrics use the selected window. Goal progress is a current snapshot because historical goal changes are not stored.</p><div class="analytics-date">☾ ${niceDate(now,{weekday:'long',month:'long',day:'numeric',year:'numeric'})}</div></div><div class="life-score"><div class="score-ring" style="${donut(lifeScore)}"><div class="score-ring-inner"><strong>${scoreParts.length?lifeScore+'%':'—'}</strong><span>tracked score</span></div></div><div class="score-caption">Average of available task completion, habit consistency, and current goal progress</div></div></div>
      <div class="stat-grid analytics-stats">
        <div class="stat-card"><div class="stat-top">Task completion <span class="stat-icon">✓</span></div><div class="stat-value">${rangeTasks.length?taskPct+'%':'—'}</div><div class="mini-progress"><span style="width:${taskPct}%"></span></div><div class="stat-foot">${taskDone} completed · ${taskOpen} open</div><div class="stat-trend">${pctTrend(taskPct,priorTasks.length?Math.round(priorTasks.filter(t=>t.done).length/priorTasks.length*100):0)}</div></div>
        <div class="stat-card"><div class="stat-top">Habit consistency <span class="stat-icon">↻</span></div><div class="stat-value">${habitPossible?habitPct+'%':'—'}</div><div class="mini-progress"><span style="width:${habitPct}%"></span></div><div class="stat-foot">${habitChecked} / ${habitPossible} possible check-ins</div><div class="stat-trend">${pctTrend(habitPct,priorHabitPossible?Math.round(priorHabitChecked/priorHabitPossible*100):0)}</div></div>
        <div class="stat-card"><div class="stat-top">Focus time <span class="stat-icon">◷</span></div><div class="stat-value">${focusInRange}<span class="stat-suffix"> min</span></div><div class="mini-progress"><span style="width:${Math.min(100,focusInRange/Math.max(1,days.length*60)*100)}%"></span></div><div class="stat-foot">${Math.floor(focusInRange/60)}h ${focusInRange%60}m · ${focusSessions} focus sessions</div><div class="stat-trend">${trend(focusInRange,focusPrior," min")}</div></div>
        <div class="stat-card"><div class="stat-top">Goal progress <span class="stat-icon">◎</span></div><div class="stat-value">${data.goals.length?goalPct+'%':'—'}</div><div class="mini-progress"><span style="width:${goalPct}%"></span></div><div class="stat-foot">${data.goals.length} goals · ${goalsCompleted} completed</div><div class="stat-trend"><span class="trend-neutral">Current snapshot, not historical trend</span></div></div>
      </div>
      <div class="analytics-grid">
        <section class="panel analytics-panel"><div class="panel-heading"><div><h3>Task status breakdown</h3><p>Current status of tasks created in this window</p></div><span class="stat-icon">◉</span></div><div class="donut-layout"><div class="donut-chart" style="${pie(statusCounts)}"><div class="donut-hole"><strong>${rangeTasks.length}</strong><span>tasks</span></div></div><div class="donut-legend">${legend(statusCounts,rangeTasks.length)}</div></div></section>
        <section class="panel analytics-panel"><div class="panel-heading"><div><h3>Task priority mix</h3><p>Priority distribution in this window</p></div><span class="stat-icon">◉</span></div><div class="donut-layout"><div class="donut-chart" style="${pie(priorityCounts)}"><div class="donut-hole"><strong>${rangeTasks.length}</strong><span>tasks</span></div></div><div class="donut-legend">${legend(priorityCounts,rangeTasks.length)}</div></div></section>
      </div>
      <div class="analytics-grid analytics-grid-wide"><section class="panel"><div class="panel-heading"><div><h3>Focus rhythm</h3><p>Daily focus minutes · most recent 7 days</p></div><button class="text-link" data-action="go-focus">Open focus →</button></div><div class="chart-bars analytics-bars">${focusDays.map(d=>`<div class="chart-bar-wrap"><em>${d.focus}m</em><div class="chart-bar" style="height:${Math.max(3,d.focus/maxFocus*100)}%"></div><small>${d.label}</small></div>`).join('')}</div><div class="chart-summary"><span>${rangeLabel} total</span><b>${focusInRange} minutes</b></div></section>
      <section class="panel"><div class="panel-heading"><div><h3>Habit check-in split</h3><p>Completed vs missed opportunities in the selected period</p></div><button class="text-link" data-action="go-habits">Manage →</button></div><div class="donut-layout"><div class="donut-chart habit-donut" style="${pie([{name:"Checked in",count:habitChecked,color:"#75d9cb"},{name:"Missed",count:Math.max(0,habitPossible-habitChecked),color:"#343653"}])}"><div class="donut-hole"><strong>${habitPossible?habitPct+"%":"—"}</strong><span>checked in</span></div></div><div class="donut-legend">${legend([{name:"Checked in",count:habitChecked,color:"#75d9cb"},{name:"Missed",count:Math.max(0,habitPossible-habitChecked),color:"#343653"}],habitPossible)}</div></div></section></div>
      <div class="analytics-bottom-grid"><section class="panel"><div class="panel-heading"><div><h3>Today's priorities</h3><p>What is on your plate today</p></div><button class="text-link" data-action="go-tasks">All tasks →</button></div><div class="task-list">${tasks.length?tasks.map(taskRow).join(''):empty('✧','Nothing urgent on the list','No tasks due today. Add one when you need it.','new-task','＋ Add a task')}</div></section><section class="panel"><div class="panel-heading"><div><h3>Recent activity</h3><p>Your latest updates</p></div><button class="text-link" data-action="go-insights">Full insights →</button></div><div class="activity-list">${data.activity.slice(0,5).map(a=>`<div class="activity-item"><div class="activity-bullet">${a.type==='task'?'✓':a.type==='habit'?'↻':a.type==='goal'?'◎':a.type==='journal'?'▤':'✦'}</div><div class="activity-copy">${escapeHTML(a.text)}<small>${new Date(a.at).toLocaleString()}</small></div></div>`).join('')||empty('⌁','Your activity will appear here','As you use NOCTURNE, this panel will show your recent progress.')}</div></section></div>`;
  }
  function renderTasks(){
    const filtered=data.tasks.filter(t=>(taskFilter==="all"||(taskFilter==="active"&&!t.done)||(taskFilter==="done"&&t.done))&&(!taskQuery||`${t.title} ${t.description||""} ${t.category||""} ${(t.tags||[]).join(" ")}`.toLowerCase().includes(taskQuery.toLowerCase()))).sort((a,b)=>(a.done?1:0)-(b.done?1:0)||(a.due||"9999").localeCompare(b.due||"9999"));
    const action=button("＋ New task","new-task");
    return `${heading("MAKE SPACE FOR WHAT MATTERS","Tasks","Capture your to-dos, choose your priorities, and move one thing forward.",action)}
      <div class="filters-row"><button class="pill ${taskFilter==="all"?"active":""}" data-task-filter="all">All tasks (${data.tasks.length})</button><button class="pill ${taskFilter==="active"?"active":""}" data-task-filter="active">To do (${data.tasks.filter(t=>!t.done).length})</button><button class="pill ${taskFilter==="done"?"active":""}" data-task-filter="done">Completed (${data.tasks.filter(t=>t.done).length})</button><input class="filter-select" id="taskSearch" placeholder="Filter tasks..." value="${escapeHTML(taskQuery)}" style="margin-left:auto"></div>
      <div class="task-board">${["To do","In progress","Completed"].map((status,i)=>{const arr=filtered.filter(t=>i===0?!t.done&&t.status!=="In progress":i===1?!t.done&&t.status==="In progress":t.done);return `<section class="board-column"><div class="board-title">${status}<span>${arr.length}</span></div>${arr.map(t=>`<article class="board-card"><div class="inline-actions"><input type="checkbox" class="check-circle" data-toggle-task="${t.id}" ${t.done?"checked":""}><b>${escapeHTML(t.title)}</b></div>${t.description?`<p style="font-size:10px;color:#989bb8;line-height:1.5;margin:8px 0 0">${escapeHTML(t.description)}</p>`:""}<small>${t.due?`◷ ${dayLabel(t.due)} · `:""}${escapeHTML(t.priority||"Medium")} priority <button class="small-icon" data-edit="task:${t.id}" style="float:right">✎</button></small></article>`).join("")||`<p class="muted" style="font-size:10px;text-align:center;padding:18px 0">Nothing here yet.</p>`}</section>`}).join("")}</div>
      <section class="panel" style="margin-top:17px"><div class="panel-heading"><div><h3>All tasks</h3><p>Full list for quick scanning and editing.</p></div><span class="tag">${filtered.length} items</span></div><div class="task-list">${filtered.length?filtered.map(taskRow).join(""):empty("☑","Nothing matches","Try another filter or create a new task.","new-task","＋ New task")}</div></section>`;
  }
  function renderCalendar(){
    const year=calendarDate.getFullYear(),month=calendarDate.getMonth(),first=new Date(year,month,1),start=(first.getDay()+(data.settings.weekStartsMonday?6:0))%7,days=new Date(year,month+1,0).getDate(),prevDays=new Date(year,month,0).getDate();
    const cells=[];for(let i=0;i<42;i++){let n=i-start+1,d,muted=false;if(n<1){d=new Date(year,month-1,prevDays+n);muted=true}else if(n>days){d=new Date(year,month+1,n-days);muted=true}else d=new Date(year,month,n);const iso=todayKey(d),items=data.tasks.filter(t=>t.due===iso),isToday=iso===todayKey();cells.push(`<button class="calendar-day ${muted?"muted":""} ${isToday?"today":""} ${selectedDate===iso?"selected":""}" data-select-date="${iso}">${d.getDate()}${items.length?`<span class="day-dots">${items.slice(0,3).map(()=>"<i></i>").join("")}</span>`:""}</button>`)}
    const dayTasks=data.tasks.filter(t=>t.due===selectedDate).sort((a,b)=>(a.done?1:0)-(b.done?1:0));
    return `${heading("SEE YOUR TIME CLEARLY","Calendar","A view of your commitments, one day at a time.",button("＋ Add task on selected day","new-task"))}
      <div class="calendar-layout"><section class="panel"><div class="calendar-toolbar"><button data-calendar-move="-1">←</button><h3>${calendarDate.toLocaleDateString(undefined,{month:"long",year:"numeric"})}</h3><div><button data-calendar-today="true">Today</button> <button data-calendar-move="1">→</button></div></div><div class="calendar-grid">${(data.settings.weekStartsMonday?["Mon","Tue","Wed","Thu","Fri","Sat","Sun"]:["Sun","Mon","Tue","Wed","Thu","Fri","Sat"]).map(d=>`<div class="calendar-weekday">${d}</div>`).join("")}${cells.join("")}</div><div class="task-meta" style="margin-top:14px"><span><i class="priority-dot priority-high"></i>Task scheduled</span><span>Outlined day = today</span></div></section>
      <section class="panel"><div class="panel-heading"><div><h3>${selectedDate===todayKey()?"Today's agenda":niceDate(new Date(selectedDate+"T12:00:00"),{weekday:"long",month:"long",day:"numeric"})}</h3><p>Everything attached to this day.</p></div><button class="text-link" data-action="new-task">＋</button></div><div class="task-list">${dayTasks.length?dayTasks.map(taskRow).join(""):empty("▦","Nothing scheduled","This day is open. Add a task if something belongs here.","new-task","＋ Schedule task")}</div></section></div>`;
  }
  function renderFocus(){
    const modes={focus:data.settings.focus,short:data.settings.shortBreak,long:data.settings.longBreak},mins=modes[timerMode]||25,elapsed=mins*60-timerRemaining,pct=Math.max(0,Math.min(100,elapsed/(mins*60)*100)),total=data.sessions.filter(s=>s.date===todayKey()).reduce((n,s)=>n+s.minutes,0);
    return `${heading("PROTECT YOUR ATTENTION","Focus room","Give one thing your full attention. Everything else can wait.",button("Focus settings","go-settings","secondary-button"))}
      <div class="dashboard-grid"><section class="panel timer-panel"><div class="timer-mode">${Object.entries({focus:"Focus",short:"Short break",long:"Long break"}).map(([k,v])=>`<button data-timer-mode="${k}" class="${timerMode===k?"active":""}">${v}</button>`).join("")}</div><div class="timer-ring" style="--timer-progress:${pct}%"><div class="timer-inner"><div class="timer-time" id="timerTime">${formatTime(timerRemaining)}</div><div class="timer-caption" id="timerCaption">${timerRunning?"Stay with this moment":timerMode==="focus"?"One thing at a time":"Rest is part of the work"}</div></div></div><div class="timer-actions"><button class="primary-button" id="timerStart">${timerRunning?"Pause session":"Start focus"}</button><button class="secondary-button" id="timerReset">Reset</button><button class="secondary-button" id="timerSkip">Skip</button></div><p class="timer-note">A gentle rhythm, not a rule. You can pause, reset, or change the duration in settings. Completed focus sessions are recorded in your local history.</p></section>
      <div style="display:flex;flex-direction:column;gap:16px"><section class="panel"><div class="panel-heading"><div><h3>Today's focus</h3><p>Intentional time adds up.</p></div><span class="stat-icon">◷</span></div><div class="stat-value">${total}<span class="muted" style="font-size:13px"> min</span></div><div class="stat-foot">${Math.floor(total/60)}h ${total%60}m recorded today</div><div class="progress-label"><span>Sessions today</span><b>${data.sessions.filter(s=>s.date===todayKey()&&s.mode==="focus").length}</b></div></section>
      <section class="panel"><div class="panel-heading"><div><h3>Recent sessions</h3><p>Your quiet wins.</p></div></div>${data.sessions.slice(-5).reverse().map(s=>`<div class="activity-item"><div class="activity-bullet">${s.mode==="focus"?"◷":"☕"}</div><div class="activity-copy">${s.mode==="focus"?"Focus session":"Break"} · ${s.minutes} minutes<small>${new Date(s.at).toLocaleString(undefined,{month:"short",day:"numeric",hour:"numeric",minute:"2-digit"})}</small></div></div>`).join("")||empty("◷","No sessions yet","Start a focus timer to record your first session.")}</section></div></div>`;
  }
  function formatTime(sec){return `${String(Math.floor(sec/60)).padStart(2,"0")}:${String(sec%60).padStart(2,"0")}`}
  function stopTimer(){if(timerInterval)clearInterval(timerInterval);timerInterval=null;timerRunning=false}
  function switchTimerMode(mode){stopTimer();timerMode=mode;timerRemaining=(data.settings[{focus:"focus",short:"shortBreak",long:"longBreak"}[mode]]||25)*60;render()}
  function finishTimer(){stopTimer();const minutes=(data.settings[{focus:"focus",short:"shortBreak",long:"longBreak"}[timerMode]]||25);data.sessions.push({id:uid(),mode:timerMode,minutes,date:todayKey(),at:new Date().toISOString()});save();logActivity("focus",`${timerMode==="focus"?"Focus session":"Break"} completed · ${minutes} minutes`);toast(timerMode==="focus"?"Focus session complete. Nice work.":"Break complete. Welcome back.");timerRemaining=0;render()}
  function renderGoals(){return `${heading("KEEP YOUR WHY IN SIGHT","Goals","Make the bigger picture tangible with milestones and progress.",button("＋ New goal","new-goal"))}<div class="section-grid">${data.goals.map(g=>`<article class="content-card"><div class="card-topline"><div class="card-symbol">◎</div><button class="card-menu" data-edit="goal:${g.id}">···</button></div><h3>${escapeHTML(g.title)}</h3><p>${escapeHTML(g.description||"A goal worth moving toward.")}</p><div class="progress-label"><span>${g.status==="Completed"?"Completed":escapeHTML(g.status||"In progress")}</span><b>${Math.min(100,Number(g.progress)||0)}%</b></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,Number(g.progress)||0)}%"></div></div><div class="card-bottom"><span>${g.target?`Target ${dayLabel(g.target)}`:"No target date"}</span><span>${(g.milestones||[]).filter(m=>m.done).length}/${(g.milestones||[]).length} milestones</span></div>${(g.milestones||[]).length?`<div class="divider"></div>${g.milestones.map((m,i)=>`<label style="display:flex;align-items:center;gap:8px;margin:8px 0;font-size:10px;color:#b2b4ce"><input type="checkbox" data-milestone="${g.id}:${i}" ${m.done?"checked":""}> <span style="${m.done?"text-decoration:line-through;opacity:.65":""}">${escapeHTML(m.title)}</span></label>`).join("")}`:""}</article>`).join("")}${!data.goals.length?`<div class="panel" style="grid-column:1/-1">${empty("◎","Every direction starts somewhere","Create a goal and break it into manageable milestones.","new-goal","＋ Create your first goal")}</div>`:""}</div>`}
  function habitStreak(id){let n=0,d=new Date();if(!isHabitDone(id,todayKey()))d.setDate(d.getDate()-1);for(let i=0;i<365;i++){if(isHabitDone(id,todayKey(d)))n++;else break;d.setDate(d.getDate()-1)}return n}
  function renderHabits(){const days=["M","T","W","T","F","S","S"];return `${heading("SMALL RITUALS, STEADY CHANGE","Habits","Track the routines that help you feel like yourself.",button("＋ New habit","new-habit"))}<section class="panel"><div class="panel-heading"><div><h3>Your rituals</h3><p>Check in when you've done a habit today.</p></div><span class="tag">${data.habits.filter(h=>isHabitDone(h.id)).length}/${data.habits.length} today</span></div>${data.habits.map(h=>`<div class="habit-big-row"><div class="habit-emoji">${escapeHTML(h.emoji||"✦")}</div><div class="habit-info"><b>${escapeHTML(h.name)}</b><small>${escapeHTML(h.description||"Show up in your own way")} · ${habitStreak(h.id)} day streak</small><div class="habit-week">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const iso=todayKey(d);return `<span><i class="${isHabitDone(h.id,iso)?"on":""}"></i>${days[(d.getDay()+6)%7]}</span>`}).join("")}</div></div><button class="habit-check ${isHabitDone(h.id)?"checked":""}" data-toggle-habit="${h.id}" aria-label="Toggle habit">${isHabitDone(h.id)?"✓":"＋"}</button><button class="small-icon" data-edit="habit:${h.id}" title="Edit habit">✎</button></div>`).join("")}${!data.habits.length?empty("↻","Your rhythm starts here","Pick one small routine you'd like to make space for.","new-habit","＋ Create a habit"):""}</section>`}
  function renderJournal(){const notes=[...data.notes].sort((a,b)=>(b.pinned?1:0)-(a.pinned?1:0)||b.updatedAt.localeCompare(a.updatedAt));return `${heading("A HOME FOR YOUR THOUGHTS","Journal & Notes","Keep the ideas, memories, and little moments you want to return to.",`<div class="inline-actions">${button("＋ Journal entry","new-journal")}${button("＋ Quick note","new-note","secondary-button")}</div>`)}
    <div class="two-col" style="margin-bottom:17px"><section class="panel"><div class="panel-heading"><div><h3>Recent reflections</h3><p>Your words, kept in one place.</p></div><button class="text-link" data-action="new-journal">＋ Write</button></div>${data.journal.slice().reverse().slice(0,4).map(j=>`<article class="journal-entry"><small>${niceDate(new Date(j.date+"T12:00:00"),{month:"long",day:"numeric",year:"numeric"})}${j.mood?` · ${escapeHTML(j.mood)}`:""}</small><h3>${escapeHTML(j.title)}</h3><p>${escapeHTML(j.body)}</p></article>`).join("")||empty("▤","A page waiting for you","Write a reflection, capture a memory, or simply let your thoughts land.","new-journal","＋ Write an entry")}</section><section class="panel"><div class="panel-heading"><div><h3>Quick capture</h3><p>Don't let a good idea disappear.</p></div><span class="stat-icon">✎</span></div>${notes.length?`<div class="activity-list">${notes.slice(0,4).map(n=>`<div class="activity-item"><div class="activity-bullet">${n.pinned?"⌑":"▤"}</div><div class="activity-copy"><b>${escapeHTML(n.title)}</b><small>${dayLabel(n.updatedAt.slice(0,10))} · ${escapeHTML((n.tags||[]).join(", "))}</small></div><button class="small-icon" data-edit="note:${n.id}">✎</button></div>`).join("")}<button class="secondary-button" data-action="new-note" style="width:100%;margin-top:12px">＋ New note</button>`:empty("✧","Capture the thought","Notes are a place for ideas that aren't ready to be anything else.","new-note","＋ Add a note")}</section></div>
    <div class="panel-heading"><div><h3>All notes</h3><p>${notes.length} saved note${notes.length===1?"":"s"}</p></div><input id="noteSearch" class="filter-select" placeholder="Search notes..." style="max-width:200px"></div><div class="note-grid" id="noteGrid">${notes.map(noteCard).join("")}${!notes.length?`<div class="panel" style="grid-column:1/-1">${empty("▤","Your archive is ready","Save a thought, idea, checklist, or anything worth keeping.","new-note","＋ Create a note")}</div>`:""}</div>`}
  function noteCard(n){return `<article class="note-card ${n.pinned?"pinned":""}" data-note-card="${n.id}"><div class="inline-actions"><span class="tag">${n.pinned?"⌑ Pinned":"✧ Note"}</span><div class="note-actions" style="margin-left:auto"><button data-pin-note="${n.id}" title="Pin note">${n.pinned?"⌑":"◇"}</button><button data-edit="note:${n.id}" title="Edit note">✎</button><button data-delete="note:${n.id}" title="Delete note">×</button></div></div><h3>${escapeHTML(n.title)}</h3><p>${escapeHTML(n.body)}</p><footer><span>${dayLabel(n.updatedAt.slice(0,10))}</span><span>${escapeHTML((n.tags||[]).join(" · "))}</span></footer></article>`}
  function renderInsights(){
    const last7=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const iso=todayKey(d);return {iso,label:d.toLocaleDateString(undefined,{weekday:"short"}),done:data.tasks.filter(t=>t.completedAt?.slice(0,10)===iso).length,focus:data.sessions.filter(s=>s.date===iso).reduce((n,s)=>n+s.minutes,0)}});
    const maxTask=Math.max(1,...last7.map(d=>d.done)),maxFocus=Math.max(1,...last7.map(d=>d.focus)),done=data.tasks.filter(t=>t.done).length,total=data.tasks.length,mins=data.sessions.reduce((n,s)=>n+s.minutes,0),habitTotal=Object.values(data.habitLogs).reduce((n,a)=>n+a.length,0);
    return `${heading("NOTICE YOUR PROGRESS","Insights","Patterns from your own data. No scores, no pressure, just perspective.",button("Export data","export-data","secondary-button"))}
      <div class="stat-grid"><div class="stat-card"><div class="stat-top">Task completion<span class="stat-icon">✓</span></div><div class="stat-value">${total?Math.round(done/total*100):0}%</div><div class="stat-foot">${done} of ${total} tasks complete</div></div><div class="stat-card"><div class="stat-top">Focus time total<span class="stat-icon">◷</span></div><div class="stat-value">${Math.floor(mins/60)}<span class="muted" style="font-size:13px">h</span> ${mins%60}<span class="muted" style="font-size:13px">m</span></div><div class="stat-foot">${data.sessions.length} recorded sessions</div></div><div class="stat-card"><div class="stat-top">Habit check-ins<span class="stat-icon">↻</span></div><div class="stat-value">${habitTotal}</div><div class="stat-foot">Across all tracked days</div></div><div class="stat-card"><div class="stat-top">Goals completed<span class="stat-icon">◎</span></div><div class="stat-value">${data.goals.filter(g=>g.status==="Completed").length}</div><div class="stat-foot">${data.goals.length} total goals created</div></div></div>
      <div class="insight-grid"><section class="panel"><div class="panel-heading"><div><h3>Tasks completed</h3><p>Last 7 days</p></div><span class="stat-icon">✓</span></div><div class="chart-bars">${last7.map(d=>`<div class="chart-bar-wrap"><em>${d.done}</em><div class="chart-bar" style="height:${Math.max(3,d.done/maxTask*100)}%"></div><small>${d.label}</small></div>`).join("")}</div></section><section class="panel"><div class="panel-heading"><div><h3>Focus minutes</h3><p>Last 7 days</p></div><span class="stat-icon">◷</span></div><div class="chart-bars">${last7.map(d=>`<div class="chart-bar-wrap"><em>${d.focus}</em><div class="chart-bar" style="height:${Math.max(3,d.focus/maxFocus*100)}%"></div><small>${d.label}</small></div>`).join("")}</div></section></div>
      <section class="panel" style="margin-top:16px"><div class="panel-heading"><div><h3>Recent activity</h3><p>Your latest actions in NOCTURNE</p></div></div>${data.activity.length?data.activity.slice(0,20).map(a=>`<div class="activity-item"><div class="activity-bullet">${a.type==="task"?"✓":a.type==="habit"?"↻":a.type==="goal"?"◎":a.type==="journal"?"▤":"✦"}</div><div class="activity-copy">${escapeHTML(a.text)}<small>${new Date(a.at).toLocaleString()}</small></div></div>`).join(""):empty("⌁","Your data tells a story over time","Start using tasks, habits, and focus sessions to see your personal patterns.")}</section>`;
  }
  function renderSettings(){return `${heading("MAKE IT YOURS","Settings & backups","Shape your space and keep your data in your hands.",`<button class="secondary-button" data-action="export-data">↓ Export backup</button>`)}
    <div class="settings-layout"><nav class="settings-tabs"><button class="active" data-settings-tab="general">General</button><button data-settings-tab="appearance">Appearance</button><button data-settings-tab="focus">Focus timer</button><button data-settings-tab="data">Data & privacy</button></nav><div class="panel" id="settingsPanel">
      <section class="settings-section" data-settings-section="general"><h3>Personal workspace</h3><p>Make this space feel like yours.</p><div class="settings-row"><div><b>Your display name</b><small>Used in your dashboard greeting.</small></div><input class="field-input" id="settingName" value="${escapeHTML(data.profile.name)}" maxlength="40"></div><div class="settings-row"><div><b>Daily reminder</b><small>A sentence to keep nearby.</small></div><input class="field-input" id="settingQuote" value="${escapeHTML(data.profile.quote)}" maxlength="100"></div><div class="settings-row"><div><b>Start week on Monday</b><small>Changes the calendar layout.</small></div><input type="checkbox" class="switch" id="settingMonday" ${data.settings.weekStartsMonday?"checked":""}></div><div class="settings-row"><div><b>Show completed tasks</b><small>Keep completed items visible in your task lists.</small></div><input type="checkbox" class="switch" id="settingCompleted" ${data.settings.showCompleted?"checked":""}></div></section>
      <section class="settings-section" data-settings-section="appearance"><h3>Appearance</h3><p>Keep the midnight atmosphere or change your accent.</p><div class="settings-row"><div><b>Accent color</b><small>Choose the highlight color used throughout the app.</small></div><div class="accent-options">${[["violet","#9c8aff"],["blue","#75baff"],["rose","#f49acb"],["teal","#74dccc"]].map(([k,c])=>`<button class="accent-choice ${data.profile.accent===k?"active":""}" style="background:${c}" data-accent-choice="${k}" aria-label="${k} accent"></button>`).join("")}</div></div><div class="settings-row"><div><b>Interface theme</b><small>NOCTURNE currently uses a deep-night interface.</small></div><span class="tag">Midnight · Default</span></div></section>
      <section class="settings-section" data-settings-section="focus"><h3>Focus timer</h3><p>Adjust the rhythm to fit your attention and energy.</p><div class="settings-row"><div><b>Focus duration</b><small>Minutes per focus session.</small></div><input class="field-input" type="number" id="settingFocus" min="1" max="180" value="${data.settings.focus}"></div><div class="settings-row"><div><b>Short break</b><small>Minutes between focus sessions.</small></div><input class="field-input" type="number" id="settingShort" min="1" max="60" value="${data.settings.shortBreak}"></div><div class="settings-row"><div><b>Long break</b><small>Minutes for a longer reset.</small></div><input class="field-input" type="number" id="settingLong" min="1" max="90" value="${data.settings.longBreak}"></div><button class="primary-button" id="saveFocusSettings">Save timer settings</button></section>
      <section class="settings-section" data-settings-section="data"><h3>Data & privacy</h3><p>Your information is stored in this browser's local storage. It is not synced to an account or automatically sent to a server.</p><div class="settings-row"><div><b>Export a backup</b><small>Download your workspace as a JSON file.</small></div><button class="secondary-button" data-action="export-data">Export JSON</button></div><div class="settings-row"><div><b>Import a backup</b><small>Restore data from a NOCTURNE JSON backup.</small></div><label class="secondary-button" for="importFile">Choose file</label><input type="file" id="importFile" accept="application/json,.json" hidden></div><div class="settings-row"><div><b>Load demo data</b><small>Add example tasks, goals, and habits so you can explore.</small></div><button class="secondary-button" data-action="demo-data">Load examples</button></div><div class="settings-row"><div><b>Clear workspace</b><small>Erase local NOCTURNE data in this browser. Export first if you want a backup.</small></div><button class="danger-button" data-action="clear-data">Clear all data</button></div><div class="divider"></div><p style="margin-bottom:0">Security note: local storage is not encrypted by default. Anyone who can use this browser profile may be able to access this data. Avoid storing passwords or highly sensitive information here.</p></section>
    </div></div>`}
  function render(){const map={overview:renderOverview,tasks:renderTasks,calendar:renderCalendar,focus:renderFocus,goals:renderGoals,habits:renderHabits,journal:renderJournal,insights:renderInsights,settings:renderSettings};$("#viewContainer").innerHTML=(map[currentView]||renderOverview)();$("#navTaskCount").textContent=data.tasks.filter(t=>!t.done).length;$("#profileName").textContent=data.profile.name||"Your profile";$("#avatarInitials").textContent=(data.profile.name||"N").trim().charAt(0).toUpperCase();$("#sidebarQuote").textContent=data.profile.quote||"Small steps still move you forward.";document.body.dataset.accent=data.profile.accent||"violet";}
  const schemas={
    task:{title:"Task",fields:[["title","Task name","text",true],["description","Description","textarea"],["due","Due date","date"],["priority","Priority","select",false,["Low","Medium","High"]],["status","Status","select",false,["To do","In progress"]],["category","Category","text"],["tags","Tags","text"]]},
    goal:{title:"Goal",fields:[["title","Goal title","text",true],["description","Description","textarea"],["target","Target date","date"],["category","Life area","select",false,["Personal","Learning","Health","Creative","School","Work","Other"]],["progress","Progress (%)","number"],["status","Status","select",false,["In progress","On hold","Completed"]],["milestones","Milestones (one per line)","textarea"]]},
    habit:{title:"Habit",fields:[["name","Habit name","text",true],["emoji","Icon / emoji","text"],["description","Description","text"]]},
    note:{title:"Note",fields:[["title","Title","text",true],["body","Your note","textarea",true],["tags","Tags (comma-separated)","text"],["pinned","Pin this note","checkbox"]]},
    journal:{title:"Journal entry",fields:[["title","Entry title","text",true],["body","What's on your mind?","textarea",true],["date","Date","date",true],["mood","Mood (optional)","select",false,["Calm","Happy","Focused","Tired","Anxious","Overwhelmed","Hopeful","Reflective","Other"]]]}
  };
  function openModal(type,id=null,extra={}){const schema=schemas[type];if(!schema)return;currentModal={type,id,extra};const old=id?findItem(type,id):null;$("#modalEyebrow").textContent=id?"EDIT "+type.toUpperCase():"CREATE NEW";$("#modalTitle").textContent=(id?"Edit ":"New ")+schema.title.toLowerCase();$("#modalSubmit").textContent=id?"Save changes":"Create "+schema.title.toLowerCase();$("#modalFields").innerHTML=schema.fields.map(([key,label,kind,required,options])=>{let val=old?.[key];if(type==="task"&&key==="due"&&!val&&extra.due)val=extra.due;if(type==="journal"&&key==="date"&&!val)val=todayKey();if(type==="task"&&key==="priority"&&!val)val="Medium";if(type==="task"&&key==="status"&&!val)val="To do";if(type==="goal"&&key==="status"&&!val)val="In progress";if(type==="goal"&&key==="progress"&&val===undefined)val=0;if(type==="habit"&&key==="emoji"&&!val)val="✦";if(key==="tags"&&Array.isArray(val))val=val.join(", ");if(key==="milestones"&&Array.isArray(val))val=val.map(m=>m.title).join("\n");if(kind==="checkbox")return `<div class="form-field full"><label style="display:flex;align-items:center;gap:9px;color:#b7b9d1;font-size:11px"><input name="${key}" type="checkbox" ${val?"checked":""}> ${label}</label></div>`;let input=kind==="textarea"?`<textarea class="field-textarea" name="${key}" ${required?"required":""}>${escapeHTML(val??"")}</textarea>`:kind==="select"?`<select class="field-select" name="${key}">${options.map(o=>`<option ${String(val??"")===o?"selected":""}>${o}</option>`).join("")}</select>`:`<input class="field-input" name="${key}" type="${kind}" value="${escapeHTML(val??"")}" ${required?"required":""} ${kind==="number"?'min="0" max="100"':""}>`;return `<div class="form-field ${kind==="textarea"||key==="description"||key==="body"||key==="milestones"?"full":""}"><label class="field-label">${label}${required?" *":""}</label>${input}</div>`}).join("");$("#modalBackdrop").classList.remove("hidden");const first=$("input:not([type=checkbox]),textarea,select",$("#modalFields"));if(first)first.focus()}
  function closeModal(){$("#modalBackdrop").classList.add("hidden");currentModal=null}
  function findItem(type,id){const arr={task:data.tasks,goal:data.goals,habit:data.habits,note:data.notes,journal:data.journal}[type];return arr?.find(x=>x.id===id)}
  function submitModal(e){e.preventDefault();if(!currentModal)return;const {type,id,extra}=currentModal,form=new FormData($("#itemForm")),obj={};for(const [k,v] of form.entries())obj[k]=v;for(const f of schemas[type].fields){const key=f[0];if(f[2]==="checkbox")obj[key]=$(`[name="${key}"]`,$("#itemForm")).checked}if(type==="task"){obj.tags=(obj.tags||"").split(",").map(s=>s.trim()).filter(Boolean);obj.done=findItem(type,id)?.done||false;obj.completedAt=findItem(type,id)?.completedAt||null;if(!obj.title?.trim())return;obj.title=obj.title.trim()}if(type==="goal"){obj.progress=Math.max(0,Math.min(100,Number(obj.progress)||0));obj.milestones=(obj.milestones||"").split("\n").map(s=>s.trim()).filter(Boolean).map((title,i)=>({title,done:findItem(type,id)?.milestones?.[i]?.done||false}));if(obj.progress===100)obj.status="Completed"}if(type==="note"){obj.tags=(obj.tags||"").split(",").map(s=>s.trim()).filter(Boolean);obj.updatedAt=new Date().toISOString();if(!obj.title?.trim())obj.title="Untitled note"}if(type==="journal"){obj.date=obj.date||todayKey();if(!obj.title?.trim())obj.title="Untitled entry"}if(type==="habit"&&!obj.name?.trim())return;
    const arr={task:data.tasks,goal:data.goals,habit:data.habits,note:data.notes,journal:data.journal}[type];if(id){const i=arr.findIndex(x=>x.id===id);if(i>=0)arr[i]={...arr[i],...obj};}else{obj.id=uid();obj.createdAt=new Date().toISOString();if(type==="note")obj.updatedAt=new Date().toISOString();if(type==="task"&&extra.due)obj.due=extra.due;arr.push(obj)}save();if(type==="task")logActivity("task",`${id?"Updated":"Created"} task: ${obj.title}`);else if(type==="goal")logActivity("goal",`${id?"Updated":"Created"} goal: ${obj.title}`);else if(type==="journal")logActivity("journal",`Saved journal entry: ${obj.title}`);else if(type==="habit")logActivity("habit",`${id?"Updated":"Created"} habit: ${obj.name}`);closeModal();render();toast(`${schemas[type].title} ${id?"updated":"created"}.`)}
  function toggleTask(id){const t=findItem("task",id);if(!t)return;t.done=!t.done;t.completedAt=t.done?new Date().toISOString():null;save();logActivity("task",`${t.done?"Completed":"Reopened"} task: ${t.title}`);render()}
  function toggleHabit(id){const logs=data.habitLogs[todayKey()]||[],done=logs.includes(id);data.habitLogs[todayKey()]=done?logs.filter(x=>x!==id):[...logs,id];save();const h=findItem("habit",id);logActivity("habit",`${done?"Unchecked":"Checked in"} habit: ${h?.name||"Habit"}`);render();toast(done?"Habit check-in removed.":"Habit checked in. Nice work.")}
  function deleteItem(type,id){const names={task:"tasks",goal:"goals",habit:"habits",note:"notes",journal:"journal"},arr=data[names[type]],item=arr.find(x=>x.id===id);if(!item)return;if(data.settings.confirmDelete&&!confirm(`Delete "${item.title||item.name||"this item"}"? This cannot be undone unless you have a backup.`))return;data.archived.push({...item,_type:type,_archivedAt:new Date().toISOString()});data[names[type]]=arr.filter(x=>x.id!==id);save();render();toast("Item deleted. A copy was moved to your archive.")}
  function exportData(){const blob=new Blob([JSON.stringify({...data,exportedAt:new Date().toISOString(),app:"NOCTURNE"},null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`nocturne-backup-${todayKey()}.json`;a.click();URL.revokeObjectURL(url);toast("Backup exported. Keep it somewhere safe.")}
  function importData(file){const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result);if(!parsed||typeof parsed!=="object"||!Array.isArray(parsed.tasks)||!Array.isArray(parsed.notes))throw new Error("This doesn't look like a NOCTURNE backup.");if(!confirm("Importing replaces the current workspace. Export your current data first if you want to keep it. Continue?"))return;data={...defaultData(),...parsed,settings:{...defaultData().settings,...parsed.settings},profile:{...defaultData().profile,...parsed.profile}};save();render();toast("Backup imported successfully.")}catch(e){toast(e.message||"Could not read that backup.","error")}};reader.readAsText(file)}
  function loadDemo(){if(data.tasks.length||data.goals.length||data.habits.length||data.notes.length){if(!confirm("Add example items to your existing workspace?"))return}const now=todayKey();data.tasks.push({id:uid(),title:"Plan a gentle start to the week",description:"Choose three priorities and leave some breathing room.",due:now,priority:"High",status:"To do",category:"Personal",tags:["planning"],done:false,createdAt:new Date().toISOString()},{id:uid(),title:"Spend 20 minutes learning something",description:"A small session counts.",due:now,priority:"Medium",status:"To do",category:"Learning",tags:[],done:false,createdAt:new Date().toISOString()},{id:uid(),title:"Clear the little things from my desk",due:"",priority:"Low",status:"In progress",category:"Home",tags:[],done:false,createdAt:new Date().toISOString()});data.goals.push({id:uid(),title:"Make space for creativity",description:"Protect time for the things that make life feel interesting.",target:"",category:"Creative",progress:25,status:"In progress",milestones:[{title:"Collect ideas",done:true},{title:"Set aside a weekly session",done:false},{title:"Finish one small project",done:false}]});data.habits.push({id:uid(),name:"Drink some water",emoji:"💧",description:"A small reset"},{id:uid(),name:"Read a few pages",emoji:"📖",description:"Keep curiosity alive"},{id:uid(),name:"Write one thought",emoji:"✍️",description:"Notice the day"});data.notes.push({id:uid(),title:"A reminder for future me",body:"You don't need to solve everything today. Start with what is in reach.",tags:["reminder","self"],pinned:true,updatedAt:new Date().toISOString(),createdAt:new Date().toISOString()});data.journal.push({id:uid(),title:"A small beginning",body:"Today I made a little space to be intentional. That is enough for a start.",date:now,mood:"Hopeful",createdAt:new Date().toISOString()});save();logActivity("system","Example workspace items added");render();toast("Example items added. Explore away.")}
  function globalSearch(q){const items=[];const add=(type,id,title,sub)=>items.push({type,id,title,sub});if(!q)return items;const term=q.toLowerCase();for(const t of data.tasks)if(`${t.title} ${t.description||""} ${t.category||""}`.toLowerCase().includes(term))add("task",t.id,t.title,`Task · ${t.done?"Completed":"To do"}`);for(const g of data.goals)if(`${g.title} ${g.description||""}`.toLowerCase().includes(term))add("goal",g.id,g.title,"Goal");for(const n of data.notes)if(`${n.title} ${n.body} ${(n.tags||[]).join(" ")}`.toLowerCase().includes(term))add("note",n.id,n.title,"Note");for(const j of data.journal)if(`${j.title} ${j.body}`.toLowerCase().includes(term))add("journal",j.id,j.title,"Journal entry");for(const h of data.habits)if(`${h.name} ${h.description||""}`.toLowerCase().includes(term))add("habit",h.id,h.name,"Habit");return items.slice(0,30)}
  function showSearchResults(){const results=globalSearch($("#globalSearch").value);searchIndex=0;$("#searchResults").innerHTML=results.length?results.map((r,i)=>`<button class="search-result" data-search-result="${r.type}:${r.id}" data-index="${i}"><span>${({task:"☑",goal:"◎",note:"▤",journal:"✎",habit:"↻"}[r.type])}</span><div><b>${escapeHTML(r.title)}</b><small>${r.sub}</small></div></button>`).join(""):`<p class="search-hint">${$("#globalSearch").value?"No matching items found.":"Type to search across your personal universe."}</p>`}
  function openSearch(){$("#searchBackdrop").classList.remove("hidden");$("#globalSearch").value="";showSearchResults();$("#globalSearch").focus()}
  function openSearchResult(key){const [type,id]=key.split(":");$("#searchBackdrop").classList.add("hidden");if(type==="task")setView("tasks");else if(type==="goal")setView("goals");else if(type==="habit")setView("habits");else setView("journal");if(type==="task"||type==="goal"||type==="habit"||type==="note"||type==="journal")openModal(type,id)}
  function handleAction(action){if(action==="new-task")openModal("task",null,currentView==="calendar"?{due:selectedDate}:{});else if(action==="new-goal")openModal("goal");else if(action==="new-habit")openModal("habit");else if(action==="new-note")openModal("note");else if(action==="new-journal")openModal("journal");else if(action==="go-tasks")setView("tasks");else if(action==="go-focus")setView("focus");else if(action==="go-habits")setView("habits");else if(action==="go-goals")setView("goals");else if(action==="go-insights")setView("insights");else if(action==="go-settings")setView("settings");else if(action==="export-data")exportData();else if(action==="demo-data")loadDemo();else if(action==="clear-data"){if(confirm("Permanently clear all NOCTURNE data from this browser? This includes tasks, notes, goals, habits, and sessions.")){localStorage.removeItem(KEY);stopTimer();data=defaultData();save();render();toast("Workspace cleared.")}}}
  document.addEventListener("click",e=>{
    const nav=e.target.closest("[data-view]");if(nav){e.preventDefault();setView(nav.dataset.view);return}
    const action=e.target.closest("[data-action]");if(action){handleAction(action.dataset.action);return}
    const toggle=e.target.closest("[data-toggle-task]");if(toggle){toggleTask(toggle.dataset.toggleTask);return}
    const habit=e.target.closest("[data-toggle-habit]");if(habit){toggleHabit(habit.dataset.toggleHabit);return}
    const edit=e.target.closest("[data-edit]");if(edit){const [type,id]=edit.dataset.edit.split(":");openModal(type,id);return}
    const del=e.target.closest("[data-delete]");if(del){const [type,id]=del.dataset.delete.split(":");deleteItem(type,id);return}
    const pin=e.target.closest("[data-pin-note]");if(pin){const n=findItem("note",pin.dataset.pinNote);if(n){n.pinned=!n.pinned;save();render()}return}
    const tf=e.target.closest("[data-task-filter]");if(tf){taskFilter=tf.dataset.taskFilter;render();return}
    const move=e.target.closest("[data-calendar-move]");if(move){calendarDate.setMonth(calendarDate.getMonth()+Number(move.dataset.calendarMove));render();return}
    if(e.target.closest("[data-calendar-today]")){calendarDate=new Date();selectedDate=todayKey();render();return}
    const day=e.target.closest("[data-select-date]");if(day){selectedDate=day.dataset.selectDate;calendarDate=new Date(selectedDate+"T12:00:00");render();return}
    const mode=e.target.closest("[data-timer-mode]");if(mode){switchTimerMode(mode.dataset.timerMode);return}
    const ms=e.target.closest("[data-milestone]");if(ms){const [gid,idx]=ms.dataset.milestone.split(":"),g=findItem("goal",gid);if(g){g.milestones[Number(idx)].done=ms.checked;const count=g.milestones.filter(m=>m.done).length;g.progress=g.milestones.length?Math.round(count/g.milestones.length*100):g.progress;if(g.progress===100)g.status="Completed";save();render()}return}
    const ac=e.target.closest("[data-accent-choice]");if(ac){data.profile.accent=ac.dataset.accentChoice;save();render();return}
    const st=e.target.closest("[data-settings-tab]");if(st){$$("[data-settings-tab]").forEach(b=>b.classList.toggle("active",b===st));$$("[data-settings-section]").forEach(s=>s.style.display=s.dataset.settingsSection===st.dataset.settingsTab?"":"none");return}
    const sr=e.target.closest("[data-search-result]");if(sr){openSearchResult(sr.dataset.searchResult);return}
  });
  $("#itemForm").addEventListener("submit",submitModal);$("#modalClose").addEventListener("click",closeModal);$("#modalCancel").addEventListener("click",closeModal);$("#modalBackdrop").addEventListener("click",e=>{if(e.target===$("#modalBackdrop"))closeModal()});
  $("#quickAdd").addEventListener("click",()=>openModal("task"));$("#searchOpen").addEventListener("click",openSearch);$("#searchBackdrop").addEventListener("click",e=>{if(e.target===$("#searchBackdrop"))$("#searchBackdrop").classList.add("hidden")});$("#globalSearch").addEventListener("input",showSearchResults);
  $("#mobileMenu").addEventListener("click",()=>$("#sidebar").classList.toggle("open"));$("#profileSettings").addEventListener("click",()=>setView("settings"));$("#themeQuick").addEventListener("click",()=>{const a=["violet","blue","rose","teal"],i=a.indexOf(data.profile.accent);data.profile.accent=a[(i+1)%a.length];save();render();toast("Accent updated.")});
  $("#viewContainer").addEventListener("input",e=>{if(e.target.id==="taskSearch"){taskQuery=e.target.value;const pos=e.target.selectionStart;render();const el=$("#taskSearch");el?.focus();el?.setSelectionRange(pos,pos)}if(e.target.id==="noteSearch"){const q=e.target.value.toLowerCase();$$("[data-note-card]").forEach(card=>card.style.display=card.textContent.toLowerCase().includes(q)?"":"none")}});
  $("#viewContainer").addEventListener("click",e=>{if(e.target.closest("[data-analytics-range]")){analyticsRange=e.target.closest("[data-analytics-range]").dataset.analyticsRange;render();return}if(e.target.id==="timerStart"){if(timerRunning){stopTimer();render()}else{timerRunning=true;sessionStartedAt=Date.now();timerInterval=setInterval(()=>{timerRemaining--;const el=$("#timerTime");if(el)el.textContent=formatTime(Math.max(0,timerRemaining));const modeLen=(data.settings[{focus:"focus",short:"shortBreak",long:"longBreak"}[timerMode]]||25)*60;const ring=$(".timer-ring");if(ring)ring.style.setProperty("--timer-progress",`${Math.max(0,(modeLen-timerRemaining)/modeLen*100)}%`);if(timerRemaining<=0)finishTimer()},1000);render()}return}if(e.target.id==="timerReset"){stopTimer();timerRemaining=(data.settings[{focus:"focus",short:"shortBreak",long:"longBreak"}[timerMode]]||25)*60;render()}if(e.target.id==="timerSkip"){stopTimer();switchTimerMode(timerMode==="focus"?"short":"focus")}if(e.target.id==="saveFocusSettings"){data.settings.focus=clampNumber($("#settingFocus").value,1,180,25);data.settings.shortBreak=clampNumber($("#settingShort").value,1,60,5);data.settings.longBreak=clampNumber($("#settingLong").value,1,90,15);timerRemaining=data.settings.focus*60;save();render();toast("Focus settings saved.")}});
  $("#viewContainer").addEventListener("change",e=>{if(e.target.id==="settingName"){data.profile.name=e.target.value.trim()||"Friend";save();render()}if(e.target.id==="settingQuote"){data.profile.quote=e.target.value.trim();save();render()}if(e.target.id==="settingMonday"){data.settings.weekStartsMonday=e.target.checked;save();render()}if(e.target.id==="settingCompleted"){data.settings.showCompleted=e.target.checked;save();render()}});
  $("#viewContainer").addEventListener("change",e=>{if(e.target.id==="importFile"&&e.target.files[0])importData(e.target.files[0])});
  function clampNumber(v,min,max,fallback){const n=Number(v);return Number.isFinite(n)?Math.max(min,Math.min(max,n)):fallback}
  document.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();openSearch()}if(e.key==="Escape"){closeModal();$("#searchBackdrop").classList.add("hidden")}if($("#searchBackdrop")&&!$("#searchBackdrop").classList.contains("hidden")){const results=$$(".search-result");if(e.key==="ArrowDown"){e.preventDefault();searchIndex=Math.min(results.length-1,searchIndex+1);results.forEach((r,i)=>r.style.background=i===searchIndex?"#242344":"")}if(e.key==="ArrowUp"){e.preventDefault();searchIndex=Math.max(0,searchIndex-1);results.forEach((r,i)=>r.style.background=i===searchIndex?"#242344":"")}if(e.key==="Enter"&&results[searchIndex])results[searchIndex].click()}});
  if("serviceWorker" in navigator && location.protocol.startsWith("http"))window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").catch(e=>console.warn("PWA worker registration failed",e)));
  render();
})();